/** 50000000-PROCESO-PGM UNTIL WKS-EOJ-VA = 1: el servicio vive mientras no reciba la orden de fin. */
@Component
@RequiredArgsConstructor
public class CicloResidente implements SmartLifecycle {
    private final RevisionBanderas revision;
    private volatile boolean activo;

    @Override public void start() { activo = true; }
    @Override public void stop()  { activo = false; revision.cierraBitacora(); }   // 80000000-FIN-APL-ARCH
    @Override public boolean isRunning() { return activo; }
}

@Component
@RequiredArgsConstructor
public class ProcesosEspecialesScheduler {

    private final RevisionBanderas revision;     // 50204000-DESPIERTO

    /**
     * ESPERACOMS devuelve un evento (mensaje, ACCEPT, HI o timeout) y después de cada uno el programa
     * revisa el reloj; solo actúa si el minuto es múltiplo de 30 y distinto del último atendido.
     * Un cron explícito reemplaza ese sondeo y elimina la dependencia del tiempo de espera de COMS.
     */
    @Scheduled(cron = "${p055.cron:0 0/30 * * * *}", zone = "America/Mexico_City")
    public void despierta() {
        revision.ejecuta(LocalDateTime.now(ZoneId.of("America/Mexico_City")));
    }
}

